  "source_text": "PyObject* JSONFileToObj(PyObject* self, PyObject *args, PyObject *kwargs)\n{\n  PyObject *read;\n  PyObject *string;\n  PyObject *result;\n  PyObject *file = NULL;\n  PyObject *argtuple;\n\n  if (!PyArg_ParseTuple (args, \"O\", &file))\n  {\n    return NULL;\n  }\n\n  if (!PyObject_HasAttrString (file, \"read\"))\n  {\n    PyErr_Format (PyExc_TypeError, \"expected file\");\n    return NULL;\n  }\n\n  read = PyObject_GetAttrString (file, \"read\");\n\n  if (!PyCallable_Check (read)) {\n    Py_XDECREF(read);\n    PyErr_Format (PyExc_TypeError, \"expected file\");\n    return NULL;\n  }\n\n  string = PyObject_CallObject (read, NULL);\n  Py_XDECREF(read);\n\n  if (string == NULL)\n  {\n    return NULL;\n  }\n\n  argtuple = PyTuple_Pack(1, string);\n\n  result = JSONToObj (self, argtuple, kwargs);\n\n  Py_XDECREF(argtuple);\n  Py_XDECREF(string);\n\n  if (result == NULL) {\n    return NULL;\n  }\n\n  return result;\n}"
}"
